 static void Pump(){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);}
 static void Until(Func<bool> done){var limit=DateTime.UtcNow.AddSeconds(20);while(!done()&&DateTime.UtcNow<limit){Pump();Thread.Sleep(10);}Check(done(),"async operation completes");}
 static T[] All<T>(DependencyObject obj)where T:DependencyObject{var list=new List<T>();for(int i=0;i<VisualTreeHelper.GetChildrenCount(obj);i++){var child=VisualTreeHelper.GetChild(obj,i);if(child is T)list.Add((T)child);list.AddRange(All<T>(child));}return list.ToArray();}
 static void Page(string name){typeof(MainWindow).GetMethod("Page",F).Invoke(main,new object[]{name});Pump();main.UpdateLayout();}
 static void Wait(Task task){Until(()=>task.IsCompleted);task.GetAwaiter().GetResult();}
 static void Save(string name){main.UpdateLayout();var bitmap=new RenderTargetBitmap((int)main.ActualWidth,(int)main.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(main);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(root,name+".png")))encoder.Save(stream);}
