 static void StartupBenchmark(){var job=Task.Run(()=>{var core=new NetworkCore(new StateStore(Path.Combine(root,"startup-benchmark")),FreePort(),FreePort(),FreePort());var state=new ClientState{VpnEnabled=false,IndependentWarpOutputs=true,Mode="proxy",DnsProvider="Системный",DnsProtocol="Системный",AutoSelect=false};try{var watch=Stopwatch.StartNew();core.Start(state);long cold=watch.ElapsedMilliseconds;Check(core.Running,"isolated local-proxy starts on ephemeral ports");core.Stop();watch.Restart();core.Start(state);long warm=watch.ElapsedMilliseconds;Check(core.ConfigurationChecks==1,"unchanged configuration validation is cached");core.Stop();state.Lists.Add(new RouteList{Name="Bench Telegram",Target="tgws",Text="telegram.test",Enabled=true,MatchMode="addresses"});watch.Restart();core.Start(state);long telegram=watch.ElapsedMilliseconds;Check(core.ConfigurationChecks==2,"changed configuration revalidates before starting");core.Stop();state.Mode="tun";watch.Restart();core.Check(core.WriteConfig(state));long tunPreflight=watch.ElapsedMilliseconds;Check(core.ConfigurationChecks==3,"TUN preflight validated without creating adapter");Console.WriteLine("METRIC startup proxy cold "+cold+" ms / warm "+warm+" ms / proxy+Telegram "+telegram+" ms / TUN preflight "+tunPreflight+" ms");File.WriteAllText(Path.Combine(root,"startup-benchmark","timings.txt"),"proxy cold "+cold+" ms\nproxy warm "+warm+" ms\nproxy+Telegram "+telegram+" ms\nTUN preflight only "+tunPreflight+" ms\nNo TUN adapter started; system routes not changed.");}finally{core.Stop();}});Wait(job);}
